/**
 * Learner accounts schema. `pnpm db:generate` turns changes here into a
 * migration in `./migrations`; `pnpm db:migrate` applies them.
 *
 * `auth-schema.ts` is generated by Better Auth's CLI (`auth generate`, then
 * Prettier) from `src/lib/auth/server.ts`; regenerate it after changing the
 * auth config. Feature tables (`course_*`, later `quiz_*`...) are hand-written
 * and reference `user.id`, so deleting an account deletes its data.
 */
export * from "./auth-schema"
export * from "./courses-schema"
